-- ---------- 书籍（企业家书单） ----------
on conflict (id) do update set title=excluded.title, author=excluded.author, emoji=excluded.emoji, grad=excluded.grad, tag=excluded.tag, rate=excluded.rate, why=excluded.why, chapters=excluded.chapters;

-- ---------- 每日箴言 ----------
on conflict (id) do update set text=excluded.text, author=excluded.author;
