insert into public.books (id, title, author, emoji, grad, tag, rate, why, chapters) values
('sz','孙子兵法','孙武 · 春秋','⚔️','linear-gradient(135deg,#0f1f2f,#1d4a5a 60%,#2a6f7f)','可阅读',5,'企业家案头第一兵书。始计·谋攻，商战博弈与战略规划全通用。','[{"t":"始计篇","paras":["孙子曰：兵者，国之大事，死生之地，存亡之道，不可不察也。","故经之以五事，校之以计，而索其情：一曰道，二曰天，三曰地，四曰将，五曰法。道者，令民与上同意也，故可以与之死，可以与之生，而不畏危。天者，阴阳、寒暑、时制也。地者，远近、险易、广狭、死生也。将者，智、信、仁、勇、严也。法者，曲制、官道、主用也。凡此五者，将莫不闻，知之者胜，不知者不胜。","故校之以计，而索其情，曰：主孰有道？将孰有能？天地孰得？法令孰行？兵众孰强？士卒孰练？赏罚孰明？吾以此知胜负矣。","将听吾计，用之必胜，留之；将不听吾计，用之必败，去之。","计利以听，乃为之势，以佐其外。势者，因利而制权也。","兵者，诡道也。能而示之不能，用而示之不用，近而示之远，远而示之近。利而诱之，乱而取之，实而备之，强而避之，怒而挠之，卑而骄之，佚而劳之，亲而离之。攻其无备，出其不意。此兵家之胜，不可先传也。","夫未战而庙算胜者，得算多也；未战而庙算不胜者，得算少也。多算胜，少算不胜，而况于无算乎！吾以此观之，胜负见矣。"]},{"t":"作战篇·节选","paras":["孙子曰：凡用兵之法，驰车千驷，革车千乘，带甲十万，千里馈粮；则内外之费，宾客之用，胶漆之材，车甲之奉，日费千金，然后十万之师举矣。","其用战也胜，久则钝兵挫锐，攻城则力屈，久暴师则国用不足。夫钝兵挫锐，屈力殚货，则诸侯乘其弊而起，虽有智者，不能善其后矣。故兵闻拙速，未睹巧之久也。夫兵久而国利者，未之有也。","故不尽知用兵之害者，则不能尽知用兵之利也。","善用兵者，役不再籍，粮不三载；取用于国，因粮于敌，故军食可足也。","国之贫于师者远输，远输则百姓贫。近于师者贵卖，贵卖则百姓财竭，财竭则急于丘役。力屈、财殚，中原内虚于家。百姓之费，十去其七；公家之费，破车罢马，甲胄矢弩，戟盾蔽橹，丘牛大车，十去其六。","故智将务食于敌，食敌一钟，当吾二十钟；萁秆一石，当吾二十石。","故杀敌者，怒也；取敌之利者，货也。故车战，得车十乘已上，赏其先得者，而更其旌旗，车杂而乘之，卒善而养之，是谓胜敌而益强。","故兵贵胜，不贵久。","故知兵之将，生民之司命，国家安危之主也。"]}]'),
('hs','货殖列传·节选','司马迁 · 西汉','📜','linear-gradient(135deg,#2a1a0a,#6a4a1a 60%,#c9a05a)','可阅读',4,'中国第一部商业智慧经典：致富之道、经营之术，两千年前的企业家心法。','[{"t":"货殖列传·节选","paras":["【编者按】《史记·货殖列传》是中国历史上第一部系统论述工商业与商人智慧的篇章，司马迁为商人立传，以下为千古传诵的节选。","太史公曰：夫神农以前，吾不知已。至若《诗》《书》所述虞夏以来，耳目欲极声色之好，口欲穷刍豢之味，身安逸乐，而心夸矜势能之荣使。俗之渐民久矣，虽户说以眇论，终不能化。故善者因之，其次利道之，其次教诲之，其次整齐之，最下者与之争。","故君子富，好行其德；小人富，以适其力。渊深而鱼生之，山深而兽往之，人富而仁义附焉。富者得势益彰，失势则客无所之，以而不乐。","谚曰：千金之子，不死于市。此非空言也。故曰：天下熙熙，皆为利来；天下攘攘，皆为利往。","故曰：仓廪实而知礼节，衣食足而知荣辱。礼生于有而废于无。故君子富，好行其德；小人富，以适其力。","无财作力，少有斗智，既饶争时，此其大经也。","以末致财，用本守之；以武一切，用文持之。变化有概，故足术也。","百里不贩樵，千里不贩籴。居之一岁，种之以谷；十岁，树之以木；百岁，来之以德。德者，人物之谓也。","贫富之道，莫之夺予，而巧者有余，拙者不足。","故善治生者，能择人而任时。十九年中而三致千金，再分散与贫交疏昆弟。此所谓富好行其德者也。","计然之策：论其有余不足，则知贵贱。贵上极则反贱，贱下极则反贵。贵出如粪土，贱取如珠玉。财币欲其行如流水。"]}]'),
